public com.educaflow.subsystem.common.db.CentroUsuario getCentroUsuarioActivo() {
    if (centroActivo == null || centroUsuarios == null) {
        return null;
    }
    return centroUsuarios.stream()
        .filter(cu -> cu.getCentro() != null && cu.getCentro().getId().equals(centroActivo.getId()))
        .findFirst()
        .orElse(null);
}

public List<TipoUsuario> getTiposUsuarioActivos() {
    var cu = getCentroUsuarioActivo();
    if (cu == null || cu.getCentroUsuarioTipoUsuario() == null) {
        return null;
    }
    return cu.getCentroUsuarioTipoUsuario().stream()
        .map(cut -> cut.getTipoUsuario())
        .collect(Collectors.toList());
}
